export const INSTALL_SH_TEMPLATE: string = "#!/usr/bin/env bash\n# Uncage installer for macOS and Linux. It connects this computer to @@SITE_URL@@.\n#\n#   curl -fsSL <site>/api/uncage/install.sh | bash               # asks [Y/n] before every change\n#   curl -fsSL <site>/api/uncage/install.sh | bash -s -- --yes   # confirms every install step\n#\n# What it does, in order: checks this computer; installs Node.js 22 when it is missing or too old\n# (with your own version manager when you have one: nvm, fnm, mise, asdf, volta or n; otherwise\n# Homebrew on macOS, else fnm in your home folder) without changing your default Node.js unless you\n# say Y; moves npm's global folder to ~/.npm-global when it is not writable; installs the CLI with\n#   npm install -g \"@uncage/cli@@@CLI_RANGE@@\"\n# finds the AI coding agents you already have; and offers to run `uncage setup`.\n# It never uses sudo, never runs a system package manager and never asks for admin rights.\n# Options: --yes (-y), --no-setup, --lang en|zh|ja, --help. Env: UNCAGE_YES=1, UNCAGE_NO_SETUP=1,\n# UNCAGE_LANG. Exit codes: 0 done, 1 a step failed, 2 needs a terminal to confirm, 3 unsupported.\n# The whole script is functions; nothing runs until the last line, so a cut-off download does nothing.\nset -euo pipefail\n\nuncage_config() {\n  CLI_RANGE='@@CLI_RANGE@@'\n  CLI_SPEC='@uncage/cli@@@CLI_RANGE@@'\n  SITE_URL='@@SITE_URL@@'\n  NODE_MAJOR=22\n  FNM_INSTALL_URL='https://fnm.vercel.app/install'\n  NODE_DOWNLOAD_URL='https://nodejs.org/en/download'\n  OWN_FNM_DIR=\"$HOME/.local/share/fnm\"\n  NPM_GLOBAL=\"$HOME/.npm-global\"\n  BLOCK_START='# >>> uncage >>>'\n  BLOCK_END='# <<< uncage <<<'\n}\n\n# @@MESSAGES@@\n\n# @@EXTENSION@@\n\n# ---- output -----------------------------------------------------------------------------------\n\nsay() {\n  uncage_msg \"$1\"\n  shift\n  # shellcheck disable=SC2059 # the format comes from the message table\n  printf -- \"$M\\n\" \"$@\"\n}\n\nwarn() {\n  uncage_msg \"$1\"\n  shift\n  # shellcheck disable=SC2059\n  printf -- \"$M\\n\" \"$@\" >&2\n}\n\n# Prints each line of $1 indented (a manual command to run).\ncmd_line() {\n  local l\n  while IFS= read -r l; do printf '    %s\\n' \"$l\"; done <<CMDS\n$1\nCMDS\n}\ncmd_line_err() { cmd_line \"$1\" >&2; }\n\n# A step failed: the reason, the commands to run by hand, exit 1.\nfail_step() {\n  local what=$1\n  shift\n  warn step_failed \"$what\"\n  if [ $# -gt 0 ]; then\n    warn manual_fix\n    local c\n    for c in \"$@\"; do cmd_line_err \"$c\"; done\n  fi\n  exit 1\n}\n\n# ---- arguments, language, terminal ------------------------------------------------------------\n\nis_true() {\n  case \"${1:-}\" in 1 | true | TRUE | yes | YES | y | Y) return 0 ;; *) return 1 ;; esac\n}\n\nparse_args() {\n  YES=0\n  NO_SETUP=0\n  SHOW_HELP=0\n  UNKNOWN_OPT=''\n  LANG_OPT=\"${UNCAGE_LANG:-}\"\n  if is_true \"${UNCAGE_YES:-}\"; then YES=1; fi\n  if is_true \"${UNCAGE_NO_SETUP:-}\"; then NO_SETUP=1; fi\n  while [ $# -gt 0 ]; do\n    case \"$1\" in\n      -y | --yes) YES=1 ;;\n      --no-setup) NO_SETUP=1 ;;\n      --lang)\n        shift\n        LANG_OPT=\"${1:-}\"\n        ;;\n      --lang=*) LANG_OPT=\"${1#--lang=}\" ;;\n      -h | --help) SHOW_HELP=1 ;;\n      *) if [ -z \"$UNKNOWN_OPT\" ]; then UNKNOWN_OPT=\"$1\"; fi ;;\n    esac\n    [ $# -gt 0 ] && shift\n  done\n}\n\n# --lang > UNCAGE_LANG > LC_ALL / LC_MESSAGES / LANG (zh*, ja*) > en\npick_lang() {\n  local l=\"$LANG_OPT\"\n  if [ -z \"$l\" ]; then l=\"${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}\"; fi\n  case \"$l\" in\n    zh*) UL=zh ;;\n    ja*) UL=ja ;;\n    *) UL=en ;;\n  esac\n}\n\n# Answers come from the terminal (stdin is this script under `curl | bash`). UNCAGE_TTY is a test hook.\ntty_available() {\n  [ \"$TTY_OPEN\" = 1 ] && return 0\n  { : <\"$UNCAGE_TTY_PATH\"; } 2>/dev/null\n}\n\nopen_tty() {\n  [ \"$TTY_OPEN\" = 1 ] && return 0\n  if tty_available; then\n    exec 3<\"$UNCAGE_TTY_PATH\"\n    TTY_OPEN=1\n    return 0\n  fi\n  return 1\n}\n\n# ask <message key> [args...]: 0 for yes. An empty answer is yes; end of input is no.\nask() {\n  local key=$1\n  shift\n  uncage_msg \"$key\"\n  # shellcheck disable=SC2059\n  printf -- \"$M [Y/n] \" \"$@\"\n  if [ \"$YES\" = 1 ]; then\n    printf 'Y (--yes)\\n'\n    return 0\n  fi\n  if ! open_tty; then\n    printf '\\n'\n    return 1\n  fi\n  local ans=''\n  if ! IFS= read -r ans <&3; then\n    printf '\\n'\n    return 1\n  fi\n  case \"$ans\" in\n    '' | y | Y | yes | Yes | YES) return 0 ;;\n    *) return 1 ;;\n  esac\n}\n\n# ---- small helpers ----------------------------------------------------------------------------\n\nfind_cmd() { command -v \"$1\" 2>/dev/null || true; }\n\nis_number() {\n  case \"${1:-}\" in '' | *[!0-9]*) return 1 ;; *) return 0 ;; esac\n}\n\ndirname_of() {\n  local p=$1\n  case \"$p\" in */*) p=\"${p%/*}\" ;; *) p=. ;; esac\n  [ -z \"$p\" ] && p=/\n  printf '%s' \"$p\"\n}\n\n# True when $1 (or its nearest existing parent) is writable.\ndir_writable() {\n  local d=$1\n  while [ ! -e \"$d\" ]; do\n    local up=''\n    up=\"$(dirname_of \"$d\")\"\n    [ \"$up\" = \"$d\" ] && return 1\n    d=$up\n  done\n  [ -w \"$d\" ]\n}\n\n# Paths under $HOME are written as \"$HOME/…\" in shell profiles.\nhome_rel() {\n  case \"$1\" in\n    \"$HOME\"/*) printf '%s' \"\\$HOME/${1#\"$HOME\"/}\" ;;\n    *) printf '%s' \"$1\" ;;\n  esac\n}\n\nsafe_path() {\n  case \"$1\" in *[\\\"\\$\\`\\\\]*) return 1 ;; *) return 0 ;; esac\n}\n\n# Runs a command with the chosen Node first on PATH (npm and uncage start with `env node`).\nwith_node() { PATH=\"$NODE_BIN:$PATH\" \"$@\" 3<&-; }\n\nsemver_of() {\n  local re='([0-9]+)\\.([0-9]+)\\.([0-9]+)'\n  if [[ \"$1\" =~ $re ]]; then\n    printf '%s.%s.%s' \"${BASH_REMATCH[1]}\" \"${BASH_REMATCH[2]}\" \"${BASH_REMATCH[3]}\"\n  fi\n}\n\n# Is version $1 (x.y.z) newer than $2?\nversion_gt() {\n  local a=$1 b=$2 ai=\"\" bi=\"\"\n  for _ in 1 2 3; do\n    ai=\"${a%%.*}\"\n    bi=\"${b%%.*}\"\n    is_number \"$ai\" || ai=0\n    is_number \"$bi\" || bi=0\n    if [ \"$ai\" -gt \"$bi\" ]; then return 0; fi\n    if [ \"$ai\" -lt \"$bi\" ]; then return 1; fi\n    case \"$a\" in *.*) a=\"${a#*.}\" ;; *) a=0 ;; esac\n    case \"$b\" in *.*) b=\"${b#*.}\" ;; *) b=0 ;; esac\n  done\n  return 1\n}\n\n# Does installed version $1 satisfy the major.minor of CLI_RANGE?\nrange_ok() {\n  local v=$1 r=\"$CLI_RANGE\" op=''\n  case \"$r\" in latest | next) return 0 ;; esac\n  case \"$r\" in\n    ^*) op='^' r=\"${r#^}\" ;;\n    '~'*) op='~' r=\"${r#\\~}\" ;;\n  esac\n  local rmaj=\"${r%%.*}\" rest='' rmin=''\n  rest=\"${r#\"$rmaj\"}\"\n  rest=\"${rest#.}\"\n  rmin=\"${rest%%.*}\"\n  rmin=\"${rmin%%-*}\"\n  local vmaj=\"${v%%.*}\" vrest='' vmin=''\n  vrest=\"${v#*.}\"\n  vmin=\"${vrest%%.*}\"\n  if ! is_number \"$rmaj\" || ! is_number \"$vmaj\" || ! is_number \"$vmin\"; then return 1; fi\n  [ \"$vmaj\" -eq \"$rmaj\" ] || return 1\n  is_number \"$rmin\" || return 0\n  if [ \"$op\" = '^' ] && [ \"$rmaj\" -gt 0 ]; then\n    [ \"$vmin\" -ge \"$rmin\" ]\n  else\n    [ \"$vmin\" -eq \"$rmin\" ]\n  fi\n}\n\n# ---- step 1: checks ---------------------------------------------------------------------------\n\ndetect_platform() {\n  OS_RAW=\"$(uname -s 2>/dev/null || true)\"\n  ARCH_RAW=\"$(uname -m 2>/dev/null || true)\"\n  case \"$OS_RAW\" in\n    Darwin) OS=macos OS_NAME=macOS ;;\n    Linux) OS=linux OS_NAME=Linux ;;\n    *) OS='' OS_NAME=\"$OS_RAW\" ;;\n  esac\n  case \"$ARCH_RAW\" in\n    x86_64 | amd64) ARCH=x64 ;;\n    arm64 | aarch64) ARCH=arm64 ;;\n    *) ARCH='' ;;\n  esac\n  if [ -z \"$OS\" ] || [ -z \"$ARCH\" ]; then\n    warn os_unsupported \"$OS_RAW\" \"$ARCH_RAW\"\n    exit 3\n  fi\n}\n\n# Sets NODE_VER for the node binary $1 ('' when it does not run).\nnode_version() {\n  local out=''\n  out=\"$(\"$1\" --version 2>/dev/null </dev/null 3<&- || true)\"\n  NODE_VER=\"$(semver_of \"$out\")\"\n}\n\nnode_major_ok() {\n  local major=\"${1%%.*}\"\n  is_number \"$major\" && [ \"$major\" -ge \"$NODE_MAJOR\" ]\n}\n\n# Uses node $1: sets NODE, NODE_BIN, NPM, NPM_PREFIX, NPM_WRITABLE.\nuse_node() {\n  NODE=$1\n  NODE_BIN=\"$(dirname_of \"$NODE\")\"\n  NPM=''\n  if [ -x \"$NODE_BIN/npm\" ]; then NPM=\"$NODE_BIN/npm\"; else NPM=\"$(find_cmd npm)\"; fi\n  NPM_VER=''\n  NPM_PREFIX=''\n  NPM_WRITABLE=0\n  [ -n \"$NPM\" ] || return 0\n  NPM_VER=\"$(with_node \"$NPM\" --version 2>/dev/null </dev/null 3<&- || true)\"\n  NPM_PREFIX=\"$(with_node \"$NPM\" config get prefix 2>/dev/null </dev/null 3<&- || true)\"\n  if [ -n \"$NPM_PREFIX\" ] && dir_writable \"$NPM_PREFIX/lib/node_modules\" && dir_writable \"$NPM_PREFIX/bin\"; then\n    NPM_WRITABLE=1\n  fi\n}\n\n# Sets UNCAGE (absolute path or '') and CLI_VER for the chosen npm prefix.\ndetect_cli() {\n  UNCAGE=''\n  CLI_VER=''\n  local c=''\n  if [ -n \"$NPM_PREFIX\" ] && [ -x \"$NPM_PREFIX/bin/uncage\" ]; then\n    c=\"$NPM_PREFIX/bin/uncage\"\n  else\n    c=\"$(find_cmd uncage)\"\n  fi\n  [ -n \"$c\" ] || return 0\n  UNCAGE=$c\n  local out=''\n  out=\"$(with_node \"$UNCAGE\" --version 2>/dev/null </dev/null 3<&- || true)\"\n  CLI_VER=\"$(semver_of \"$out\")\"\n}\n\ncli_ok() { [ -n \"$UNCAGE\" ] && [ -n \"$CLI_VER\" ] && range_ok \"$CLI_VER\"; }\n\ndetect_agents() {\n  CLAUDE=\"$(find_cmd claude)\"\n  if [ -z \"$CLAUDE\" ]; then\n    local p\n    for p in \"$HOME/.local/bin/claude\" \"$HOME/.claude/local/claude\"; do\n      if [ -x \"$p\" ]; then CLAUDE=$p && break; fi\n    done\n  fi\n  CODEX=\"$(find_cmd codex)\"\n}\n\n# Version managers, in order of preference. Only PATH and $HOME are searched.\ndetect_manager() {\n  MGR=''\n  MGR_LABEL=''\n  FNM=''\n  FNM_OWN=0\n  NVM_SH=''\n  BREW=\"$(find_cmd brew)\"\n  local nvm_dir=\"${NVM_DIR:-$HOME/.nvm}\"\n  if [ -s \"$nvm_dir/nvm.sh\" ]; then\n    NVM_SH=\"$nvm_dir/nvm.sh\"\n  elif [ -n \"$BREW\" ]; then\n    local bp=''\n    bp=\"$(\"$BREW\" --prefix 2>/dev/null </dev/null 3<&- || true)\"\n    if [ -n \"$bp\" ] && [ -s \"$bp/opt/nvm/nvm.sh\" ]; then NVM_SH=\"$bp/opt/nvm/nvm.sh\"; fi\n  fi\n  if [ -n \"$NVM_SH\" ]; then\n    MGR=nvm MGR_LABEL=nvm\n    export NVM_DIR=\"$nvm_dir\"\n    return 0\n  fi\n  FNM=\"$(find_cmd fnm)\"\n  if [ -z \"$FNM\" ] && [ -x \"$OWN_FNM_DIR/fnm\" ]; then\n    FNM=\"$OWN_FNM_DIR/fnm\"\n    FNM_OWN=1\n    export FNM_DIR=\"$OWN_FNM_DIR\"\n  fi\n  if [ -n \"$FNM\" ]; then\n    MGR=fnm MGR_LABEL=fnm\n    return 0\n  fi\n  MISE=\"$(find_cmd mise)\"\n  if [ -z \"$MISE\" ] && [ -x \"$HOME/.local/bin/mise\" ]; then MISE=\"$HOME/.local/bin/mise\"; fi\n  if [ -n \"$MISE\" ]; then\n    MGR=mise MGR_LABEL=mise\n    return 0\n  fi\n  ASDF=\"$(find_cmd asdf)\"\n  if [ -n \"$ASDF\" ]; then\n    MGR=asdf MGR_LABEL=asdf\n    return 0\n  fi\n  # volta is unmaintained: an existing install is used, never installed by this script.\n  VOLTA=\"$(find_cmd volta)\"\n  if [ -z \"$VOLTA\" ] && [ -x \"${VOLTA_HOME:-$HOME/.volta}/bin/volta\" ]; then VOLTA=\"${VOLTA_HOME:-$HOME/.volta}/bin/volta\"; fi\n  if [ -n \"$VOLTA\" ]; then\n    MGR=volta MGR_LABEL=volta\n    return 0\n  fi\n  # n installs into N_PREFIX (default /usr/local); only used when that needs no admin rights.\n  N_CMD=\"$(find_cmd n)\"\n  if [ -n \"$N_CMD\" ] && dir_writable \"${N_PREFIX:-/usr/local}/n/versions\"; then\n    MGR=n MGR_LABEL=n\n    return 0\n  fi\n}\n\ndetect() {\n  detect_platform\n  PATH_NODE=\"$(find_cmd node)\"\n  PATH_NODE_VER=''\n  NODE_OK=0\n  NODE=''\n  NODE_BIN=''\n  NPM=''\n  NPM_VER=''\n  NPM_PREFIX=''\n  NPM_WRITABLE=0\n  UNCAGE=''\n  CLI_VER=''\n  NODE_IS_DEFAULT=1\n  INSTALLED_NOW=0\n  HAD_DEFAULT=1\n  if [ -n \"$PATH_NODE\" ]; then\n    node_version \"$PATH_NODE\"\n    PATH_NODE_VER=$NODE_VER\n    if node_major_ok \"$PATH_NODE_VER\"; then\n      use_node \"$PATH_NODE\"\n      [ -n \"$NPM\" ] && NODE_OK=1\n    fi\n  fi\n  if [ \"$NODE_OK\" = 1 ]; then detect_cli; fi\n  detect_agents\n  detect_manager\n}\n\nprint_checks() {\n  say checking\n  say os_ok \"$OS_NAME\" \"$ARCH\"\n  if [ \"$NODE_OK\" = 1 ]; then\n    say node_ok \"$PATH_NODE_VER\" \"$PATH_NODE\"\n    if [ \"$NPM_WRITABLE\" = 1 ]; then\n      say npm_ok \"$NPM_VER\" \"$NPM_PREFIX\"\n    else\n      say npm_not_writable \"$NPM_VER\" \"$NPM_PREFIX\"\n    fi\n    if cli_ok; then\n      say cli_ok \"$CLI_VER\" \"$UNCAGE\"\n    elif [ -n \"$UNCAGE\" ]; then\n      say cli_old \"${CLI_VER:-?}\" \"$CLI_RANGE\"\n    else\n      say cli_missing\n    fi\n  else\n    if [ -z \"$PATH_NODE\" ] || [ -z \"$PATH_NODE_VER\" ]; then\n      say node_missing\n    elif ! node_major_ok \"$PATH_NODE_VER\"; then\n      say node_old \"$PATH_NODE_VER\"\n    else\n      say npm_missing\n    fi\n    say later\n  fi\n  if [ -n \"$CLAUDE\" ]; then say agent_ok 'Claude Code' \"$CLAUDE\"; else say agent_missing 'Claude Code'; fi\n  if [ -n \"$CODEX\" ]; then say agent_ok 'Codex' \"$CODEX\"; else say agent_missing 'Codex'; fi\n  printf '\\n'\n}\n\n# ---- manual commands (no terminal, or a declined / failed step) -------------------------------\n\nnode_manual_cmds() {\n  case \"$MGR\" in\n    nvm) printf '%s\\n' \"nvm install $NODE_MAJOR\" ;;\n    fnm) printf '%s\\n' \"fnm install $NODE_MAJOR\" ;;\n    mise) printf '%s\\n' \"mise install node@$NODE_MAJOR\" ;;\n    asdf) printf '%s\\n' \"asdf install nodejs latest:$NODE_MAJOR\" ;;\n    volta) printf '%s\\n' \"volta install node@$NODE_MAJOR\" ;;\n    n) printf '%s\\n' \"n $NODE_MAJOR\" ;;\n    *)\n      if [ \"$OS\" = macos ] && [ -n \"$BREW\" ]; then\n        printf '%s\\n' \"brew install node@$NODE_MAJOR\"\n      else\n        printf '%s\\n' \"curl -fsSL $FNM_INSTALL_URL | bash\" \"fnm install $NODE_MAJOR\"\n      fi\n      ;;\n  esac\n}\n\nprint_cmds() {\n  local line\n  while IFS= read -r line; do cmd_line \"$line\"; done\n}\n\n# No terminal and no --yes: list what is missing and how to do it by hand; change nothing.\ngate_without_terminal() {\n  local need=0\n  [ \"$NODE_OK\" = 1 ] || need=1\n  if [ \"$NODE_OK\" = 1 ]; then\n    [ \"$NPM_WRITABLE\" = 1 ] || need=1\n    cli_ok || need=1\n  fi\n  [ \"$need\" = 1 ] || return 0\n  [ \"$YES\" = 1 ] && return 0\n  tty_available && return 0\n  say needs_confirm\n  if [ \"$NODE_OK\" != 1 ]; then\n    say item_node\n    node_manual_cmds | print_cmds\n  fi\n  if [ \"$NODE_OK\" = 1 ] && [ \"$NPM_WRITABLE\" != 1 ]; then\n    say item_npm\n    cmd_line \"npm config set prefix \\\"\\$HOME/.npm-global\\\"\"\n    cmd_line \"export PATH=\\\"\\$HOME/.npm-global/bin:\\$PATH\\\"\"\n  fi\n  if [ \"$NODE_OK\" != 1 ] || ! cli_ok; then\n    say item_cli \"$CLI_SPEC\"\n    cmd_line \"npm install -g \\\"$CLI_SPEC\\\"\"\n  fi\n  say item_setup\n  cmd_line \"uncage setup $SITE_URL\"\n  say rerun_yes\n  exit 2\n}\n\n# ---- shell profile: one marked block, rewritten in place ---------------------------------------\n\nprofile_file() {\n  case \"${SHELL##*/}\" in\n    zsh) printf '%s' \"${ZDOTDIR:-$HOME}/.zshrc\" ;;\n    bash) if [ \"$OS\" = macos ]; then printf '%s' \"$HOME/.bash_profile\"; else printf '%s' \"$HOME/.bashrc\"; fi ;;\n    fish) printf '' ;;\n    *) printf '%s' \"$HOME/.profile\" ;;\n  esac\n}\n\n# add_profile_lines <line>...: merges the lines into the uncage block (each line once).\nadd_profile_lines() {\n  local file=''\n  file=\"$(profile_file)\"\n  local l\n  if [ -z \"$file\" ]; then\n    say path_fish\n    for l in \"$@\"; do cmd_line \"$l\"; done\n    return 0\n  fi\n  local nl=$'\\n' before='' block='' after='' state=0 line=''\n  if [ -f \"$file\" ]; then\n    while IFS= read -r line || [ -n \"$line\" ]; do\n      case \"$state:$line\" in\n        \"0:$BLOCK_START\") state=1 ;;\n        \"1:$BLOCK_END\") state=2 ;;\n        0:*) before=\"$before$line$nl\" ;;\n        1:*) block=\"$block$line$nl\" ;;\n        *) after=\"$after$line$nl\" ;;\n      esac\n    done <\"$file\"\n  fi\n  for l in \"$@\"; do\n    case \"$nl$block\" in\n      *\"$nl$l$nl\"*) ;;\n      *) block=\"$block$l$nl\" ;;\n    esac\n  done\n  if [ \"$state\" = 0 ] && [ -n \"$before\" ]; then before=\"$before$nl\"; fi\n  mkdir -p \"$(dirname_of \"$file\")\"\n  # The whole new content goes to a temp file first, then `cat` rewrites the same file (a\n  # symlinked profile stays a symlink, and an interrupted write never leaves it half-written).\n  local tmpf=\"$file.uncage-tmp.$$\"\n  printf '%s%s\\n%s%s\\n%s' \"$before\" \"$BLOCK_START\" \"$block\" \"$BLOCK_END\" \"$after\" >\"$tmpf\"\n  cat \"$tmpf\" >\"$file\"\n  rm -f \"$tmpf\"\n  say path_added \"$file\"\n}\n\npath_line() {\n  local d=''\n  d=\"$(home_rel \"$1\")\"\n  # shellcheck disable=SC2016 # $PATH is expanded by the shell profile, not here\n  printf 'export PATH=\"%s:$PATH\"' \"$d\"\n}\n\n# ---- step 2: Node.js 22 -----------------------------------------------------------------------\n\nnvm_run() {\n  mkdir -p \"$NVM_DIR\"\n  set +euo pipefail\n  # shellcheck disable=SC1090\n  . \"$NVM_SH\" --no-use\n  nvm \"$@\"\n  local rc=$?\n  set -euo pipefail\n  return $rc\n}\n\n# nvm and fnm make the first version they install the default by themselves. The alias file\n# tells whether a default existed before this run.\nfnm_dir() {\n  if [ -n \"${FNM_DIR:-}\" ]; then\n    printf '%s' \"$FNM_DIR\"\n  elif [ -d \"$HOME/.fnm\" ]; then\n    printf '%s' \"$HOME/.fnm\"\n  elif [ -n \"${XDG_DATA_HOME:-}\" ]; then\n    printf '%s' \"$XDG_DATA_HOME/fnm\"\n  elif [ \"$OS\" = macos ]; then\n    printf '%s' \"$HOME/Library/Application Support/fnm\"\n  else\n    printf '%s' \"$HOME/.local/share/fnm\"\n  fi\n}\n\nhas_default_alias() {\n  local a=''\n  case \"$MGR\" in\n    nvm) a=\"$NVM_DIR/alias/default\" ;;\n    fnm) a=\"$(fnm_dir)/aliases/default\" ;;\n    *) return 0 ;;\n  esac\n  [ -e \"$a\" ] || [ -L \"$a\" ]\n}\n\n# Call right before installing Node with the manager.\nrecord_default() {\n  INSTALLED_NOW=1\n  HAD_DEFAULT=1\n  if ! has_default_alias; then HAD_DEFAULT=0; fi\n}\n\n# The user kept their default: undo the default nvm / fnm created by themselves.\nrestore_default() {\n  if [ \"$INSTALLED_NOW\" != 1 ] || [ \"$HAD_DEFAULT\" != 0 ] || ! has_default_alias; then return 0; fi\n  local how=unalias\n  [ -n \"$PATH_NODE\" ] && how=system\n  case \"$MGR:$how\" in\n    nvm:system) nvm_run alias default system </dev/null 3<&- || fail_step \"nvm alias default system\" \"nvm alias default system\" ;;\n    nvm:unalias) nvm_run unalias default </dev/null 3<&- || fail_step \"nvm unalias default\" \"nvm unalias default\" ;;\n    fnm:system) \"$FNM\" default system </dev/null 3<&- || fail_step \"fnm default system\" \"fnm default system\" ;;\n    fnm:unalias) \"$FNM\" unalias default </dev/null 3<&- || fail_step \"fnm unalias default\" \"fnm unalias default\" ;;\n    *) return 0 ;;\n  esac\n  say default_restored \"$MGR_LABEL\"\n}\n\nmgr_install() {\n  record_default\n  case \"$MGR\" in\n    nvm) nvm_run install \"$NODE_MAJOR\" </dev/null 3<&- ;;\n    fnm) \"$FNM\" install \"$NODE_MAJOR\" </dev/null 3<&- ;;\n    mise) \"$MISE\" install \"node@$NODE_MAJOR\" </dev/null 3<&- ;;\n    asdf)\n      local plugins=''\n      plugins=\"$(\"$ASDF\" plugin list 2>/dev/null </dev/null 3<&- || true)\"\n      case $'\\n'\"$plugins\"$'\\n' in\n        *$'\\n'nodejs$'\\n'*) ;;\n        *) \"$ASDF\" plugin add nodejs </dev/null 3<&- ;;\n      esac\n      \"$ASDF\" install nodejs \"latest:$NODE_MAJOR\" </dev/null 3<&-\n      ;;\n    # `volta install` would also make it the default: fetch only, `install` after a Y.\n    volta) \"$VOLTA\" fetch \"node@$NODE_MAJOR\" </dev/null 3<&- ;;\n    n) \"$N_CMD\" download \"$NODE_MAJOR\" </dev/null 3<&- ;;\n  esac\n}\n\n# Sets NEW_NODE to the manager's Node 22 binary without activating it.\nmgr_node_path() {\n  NEW_NODE=''\n  local p='' d=''\n  case \"$MGR\" in\n    nvm) p=\"$(nvm_run which \"$NODE_MAJOR\" 2>/dev/null || true)\" ;;\n    fnm) p=\"$(\"$FNM\" exec \"--using=$NODE_MAJOR\" node -p process.execPath 2>/dev/null </dev/null 3<&- || true)\" ;;\n    mise)\n      d=\"$(\"$MISE\" where \"node@$NODE_MAJOR\" 2>/dev/null </dev/null 3<&- || true)\"\n      [ -n \"$d\" ] && p=\"$d/bin/node\"\n      ;;\n    asdf)\n      local list='' line=''\n      ASDF_VER=''\n      list=\"$(\"$ASDF\" list nodejs \"$NODE_MAJOR\" 2>/dev/null </dev/null 3<&- || true)\"\n      while IFS= read -r line; do\n        line=\"${line//[ *]/}\"\n        case \"$line\" in \"$NODE_MAJOR\".*) ASDF_VER=$line ;; esac\n      done <<EOF\n$list\nEOF\n      if [ -n \"$ASDF_VER\" ]; then\n        d=\"$(\"$ASDF\" where nodejs \"$ASDF_VER\" 2>/dev/null </dev/null 3<&- || true)\"\n        [ -n \"$d\" ] && p=\"$d/bin/node\"\n      fi\n      ;;\n    # Not `volta run --node 22`: it would download Node.js before the user said Y.\n    volta)\n      local cand='' v='' best='' bestv=''\n      for cand in \"${VOLTA_HOME:-$HOME/.volta}/tools/image/node/$NODE_MAJOR\".*; do\n        [ -x \"$cand/bin/node\" ] || continue\n        v=\"${cand##*/}\"\n        if [ -z \"$best\" ] || version_gt \"$v\" \"$bestv\"; then\n          best=$cand\n          bestv=$v\n        fi\n      done\n      [ -n \"$best\" ] && p=\"$best/bin/node\"\n      ;;\n    n) p=\"$(\"$N_CMD\" which \"$NODE_MAJOR\" 2>/dev/null </dev/null 3<&- || true)\" ;;\n  esac\n  p=\"${p%%$'\\n'*}\"\n  if [ -n \"$p\" ] && [ -x \"$p\" ]; then\n    node_version \"$p\"\n    if node_major_ok \"$NODE_VER\"; then NEW_NODE=$p; fi\n  fi\n  [ -n \"$NEW_NODE\" ]\n}\n\nmgr_make_default() {\n  case \"$MGR\" in\n    nvm) nvm_run alias default \"$NODE_MAJOR\" </dev/null 3<&- ;;\n    fnm)\n      \"$FNM\" default \"$NODE_MAJOR\" </dev/null 3<&-\n      if [ \"$FNM_OWN\" = 1 ]; then own_fnm_profile; fi\n      ;;\n    mise) \"$MISE\" use -g \"node@$NODE_MAJOR\" </dev/null 3<&- ;;\n    asdf) \"$ASDF\" set -u nodejs \"$ASDF_VER\" </dev/null 3<&- || \"$ASDF\" global nodejs \"$ASDF_VER\" </dev/null 3<&- ;;\n    volta) \"$VOLTA\" install \"node@$NODE_MAJOR\" </dev/null 3<&- ;;\n    n) \"$N_CMD\" \"$NODE_MAJOR\" </dev/null 3<&- ;;\n    brew) add_profile_lines \"$(path_line \"$NEW_NODE_BIN\")\" ;;\n  esac\n}\n\nown_fnm_profile() {\n  local d=''\n  d=\"$(home_rel \"$OWN_FNM_DIR\")\"\n  if [ \"${SHELL##*/}\" = fish ]; then\n    add_profile_lines \"set -gx FNM_DIR \\\"$d\\\"\" \"fish_add_path \\\"$d\\\"\" 'fnm env --shell fish | source'\n    return 0\n  fi\n  local sh=bash\n  [ \"${SHELL##*/}\" = zsh ] && sh=zsh\n  add_profile_lines \"export FNM_DIR=\\\"$d\\\"\" \"$(path_line \"$OWN_FNM_DIR\")\" \"eval \\\"\\$(fnm env --shell $sh)\\\"\"\n}\n\ndecline_node() {\n  say node_required\n  node_manual_cmds | print_cmds\n  exit 0\n}\n\ninstall_own_fnm() {\n  if [ \"$OS\" = linux ] && [ -z \"$(find_cmd unzip)\" ]; then\n    warn need_unzip\n    warn node_manual_other \"$NODE_DOWNLOAD_URL\"\n    cmd_line_err \"curl -fsSL $FNM_INSTALL_URL | bash -s -- --install-dir \\\"\\$HOME/.local/share/fnm\\\" --skip-shell\"\n    cmd_line_err \"\\\"\\$HOME/.local/share/fnm/fnm\\\" install $NODE_MAJOR\"\n    exit 1\n  fi\n  if [ -z \"$(find_cmd curl)\" ]; then\n    warn need_curl\n    warn node_manual_other \"$NODE_DOWNLOAD_URL\"\n    exit 1\n  fi\n  ask ask_node_fnm \"$(home_rel \"$OWN_FNM_DIR\")\" || decline_node\n  UNCAGE_TMP=\"$(mktemp -d \"${TMPDIR:-/tmp}/uncage-install.XXXXXX\")\"\n  trap 'rm -rf \"$UNCAGE_TMP\"' EXIT\n  local tmp=\"$UNCAGE_TMP\"\n  # Downloaded to a file first: a cut-off download never runs half a script.\n  curl --proto '=https' --tlsv1.2 -fsSL \"$FNM_INSTALL_URL\" -o \"$tmp/fnm-installer\" </dev/null 3<&- ||\n    fail_step \"curl $FNM_INSTALL_URL\" \"curl -fsSL $FNM_INSTALL_URL | bash -s -- --install-dir \\\"\\$HOME/.local/share/fnm\\\" --skip-shell --force-no-brew\"\n  bash \"$tmp/fnm-installer\" --install-dir \"$OWN_FNM_DIR\" --skip-shell --force-no-brew </dev/null 3<&- ||\n    fail_step \"fnm install\" \"curl -fsSL $FNM_INSTALL_URL | bash -s -- --install-dir \\\"\\$HOME/.local/share/fnm\\\" --skip-shell --force-no-brew\"\n  rm -rf \"$tmp\"\n  trap - EXIT\n  [ -x \"$OWN_FNM_DIR/fnm\" ] || fail_step \"fnm install\" \"curl -fsSL $FNM_INSTALL_URL | bash\"\n  MGR=fnm MGR_LABEL=fnm FNM=\"$OWN_FNM_DIR/fnm\" FNM_OWN=1\n  export FNM_DIR=\"$OWN_FNM_DIR\"\n  record_default\n  \"$FNM\" install \"$NODE_MAJOR\" </dev/null 3<&- || fail_step \"fnm install $NODE_MAJOR\" \"\\\"\\$HOME/.local/share/fnm/fnm\\\" install $NODE_MAJOR\"\n}\n\nstep_node() {\n  [ \"$NODE_OK\" = 1 ] && return 0\n  NEW_NODE=''\n  if [ -n \"$MGR\" ]; then\n    if mgr_node_path; then\n      say node_found_mgr \"$MGR_LABEL\" \"$NEW_NODE\"\n    else\n      ask ask_node_mgr \"$MGR_LABEL\" || decline_node\n      mgr_install || fail_step \"$MGR_LABEL install\" \"$(node_manual_cmds)\"\n      mgr_node_path || fail_step \"$MGR_LABEL install\" \"$(node_manual_cmds)\"\n      say node_installed \"$NODE_VER\" \"$NEW_NODE\"\n    fi\n  elif [ \"$OS\" = macos ] && [ -n \"$BREW\" ]; then\n    MGR=brew MGR_LABEL=Homebrew\n    local bp=''\n    bp=\"$(\"$BREW\" --prefix 2>/dev/null </dev/null 3<&- || true)\"\n    local keg=\"$bp/opt/node@$NODE_MAJOR/bin/node\"\n    if [ -n \"$bp\" ] && [ -x \"$keg\" ]; then\n      say node_found_mgr Homebrew \"$keg\"\n    else\n      ask ask_node_brew || decline_node\n      \"$BREW\" install \"node@$NODE_MAJOR\" </dev/null 3<&- || fail_step \"brew install node@$NODE_MAJOR\" \"brew install node@$NODE_MAJOR\"\n      [ -x \"$keg\" ] || fail_step \"brew install node@$NODE_MAJOR\" \"brew install node@$NODE_MAJOR\"\n    fi\n    node_version \"$keg\"\n    NEW_NODE=$keg\n    say node_installed \"$NODE_VER\" \"$NEW_NODE\"\n  else\n    install_own_fnm\n    mgr_node_path || fail_step \"fnm install $NODE_MAJOR\" \"\\\"\\$HOME/.local/share/fnm/fnm\\\" install $NODE_MAJOR\"\n    say node_installed \"$NODE_VER\" \"$NEW_NODE\"\n  fi\n  NEW_NODE_BIN=\"$(dirname_of \"$NEW_NODE\")\"\n  if [ \"$MGR\" = brew ] && ! safe_path \"$NEW_NODE_BIN\"; then MGR=brew-manual; fi\n  # Changing the default needs its own Y. Under --yes only when there was no Node.js at all.\n  local make_default=1\n  if [ \"$YES\" = 1 ] && [ -n \"$PATH_NODE\" ]; then\n    make_default=0\n    say default_kept_yes\n  elif ! ask ask_default; then\n    make_default=0\n  fi\n  if [ \"$make_default\" = 1 ] && [ \"$MGR\" != brew-manual ]; then\n    mgr_make_default || fail_step \"$MGR_LABEL default\" \"$(node_manual_cmds)\"\n    say default_done\n  else\n    NODE_IS_DEFAULT=0\n    restore_default\n    say default_kept \"$NEW_NODE\"\n  fi\n  use_node \"$NEW_NODE\"\n  [ -n \"$NPM\" ] || fail_step npm \"$(node_manual_cmds)\"\n  NODE_OK=1\n  detect_cli\n}\n\n# ---- step 3: npm global folder ----------------------------------------------------------------\n\nstep_npm_prefix() {\n  [ \"$NPM_WRITABLE\" = 1 ] && return 0\n  # nvm refuses to work with a `prefix` in ~/.npmrc: never set one for an nvm Node.\n  if [ \"$MGR\" = nvm ]; then\n    case \"$NODE\" in\n      \"$NVM_DIR\"/*)\n        warn nvm_prefix \"$NPM_PREFIX\"\n        exit 1\n        ;;\n    esac\n  fi\n  if ! ask ask_npm_prefix \"$NPM_PREFIX\" \"$(home_rel \"$NPM_GLOBAL\")\"; then\n    say declined\n    cmd_line \"npm config set prefix \\\"\\$HOME/.npm-global\\\"\"\n    cmd_line \"npm install -g \\\"$CLI_SPEC\\\"\"\n    exit 0\n  fi\n  mkdir -p \"$NPM_GLOBAL/bin\" \"$NPM_GLOBAL/lib\"\n  with_node \"$NPM\" config set prefix \"$NPM_GLOBAL\" </dev/null 3<&- || fail_step \"npm config set prefix\" \"npm config set prefix \\\"\\$HOME/.npm-global\\\"\"\n  NPM_PREFIX=\"$NPM_GLOBAL\"\n  NPM_WRITABLE=1\n  say npm_prefix_done \"$NPM_GLOBAL\"\n  add_profile_lines \"$(path_line \"$NPM_GLOBAL/bin\")\"\n  detect_cli\n}\n\n# ---- step 4: the Uncage CLI -------------------------------------------------------------------\n\nstep_cli() {\n  local spec=\"${UNCAGE_CLI_SPEC:-$CLI_SPEC}\"\n  if cli_ok; then\n    say cli_skip \"$CLI_VER\" \"$UNCAGE\"\n    return 0\n  fi\n  if ! ask ask_cli \"$spec\"; then\n    say declined\n    cmd_line \"npm install -g \\\"$spec\\\"\"\n    exit 0\n  fi\n  with_node \"$NPM\" install -g \"$spec\" </dev/null 3<&- || fail_step \"npm install -g $spec\" \"PATH=\\\"$NODE_BIN:\\$PATH\\\" \\\"$NPM\\\" install -g \\\"$spec\\\"\"\n  UNCAGE=''\n  if [ -x \"$NPM_PREFIX/bin/uncage\" ]; then UNCAGE=\"$NPM_PREFIX/bin/uncage\"; else UNCAGE=\"$(find_cmd uncage)\"; fi\n  [ -n \"$UNCAGE\" ] || fail_step \"npm install -g $spec\" \"PATH=\\\"$NODE_BIN:\\$PATH\\\" \\\"$NPM\\\" install -g \\\"$spec\\\"\"\n  say cli_installed \"$UNCAGE\"\n}\n\n# ---- the site's own step (HubOptions.installScript.shAfterCli) ---------------------------------\n\nrun_extension() {\n  [ -n \"$UNCAGE_EXT\" ] || return 0\n  say extension_running\n  if ! (\n    export PATH=\"$NODE_BIN:$PATH\" UNCAGE_BIN=\"$UNCAGE\" UNCAGE_NODE=\"$NODE\" UNCAGE_SITE_URL=\"$SITE_URL\"\n    eval \"$UNCAGE_EXT\"\n  ) </dev/null 3<&-; then\n    uncage_msg extension_step\n    fail_step \"$M\"\n  fi\n}\n\n# ---- step 5: agents, then step 6: setup -------------------------------------------------------\n\n# ACP agents count too, once the CLI knows them (`uncage runtimes --json`, when it exists).\nacp_available() {\n  local out=''\n  out=\"$(with_node \"$UNCAGE\" runtimes --json 2>/dev/null </dev/null 3<&- || true)\"\n  local re='\"status\"[[:space:]]*:[[:space:]]*\"available\"'\n  [[ \"$out\" =~ $re ]]\n}\n\nprint_where() {\n  if [ \"$NODE_IS_DEFAULT\" = 1 ]; then\n    say uncage_path \"\\\"$UNCAGE\\\"\"\n  else\n    say not_default_hint \"$NODE_BIN\" \"\\\"$UNCAGE\\\"\"\n  fi\n}\n\nstep_setup() {\n  if [ -z \"$CLAUDE\" ] && [ -z \"$CODEX\" ] && ! acp_available; then\n    printf '\\n'\n    say no_agent\n    print_where\n    exit 0\n  fi\n  local setup_cmd=\"\\\"$UNCAGE\\\" setup $SITE_URL\"\n  if [ \"$NODE_IS_DEFAULT\" != 1 ]; then setup_cmd=\"PATH=\\\"$NODE_BIN:\\$PATH\\\" $setup_cmd\"; fi\n  if [ \"$NO_SETUP\" = 1 ]; then\n    print_where\n    say setup_later \"$setup_cmd\"\n    exit 0\n  fi\n  if [ \"$YES\" != 1 ] && ! tty_available; then\n    print_where\n    say setup_later \"$setup_cmd\"\n    exit 0\n  fi\n  if ! ask ask_setup \"$SITE_URL\"; then\n    print_where\n    say setup_later \"$setup_cmd\"\n    exit 0\n  fi\n  if [ \"$TTY_OPEN\" = 1 ]; then\n    with_node \"$UNCAGE\" setup \"$SITE_URL\" <&3 3<&- || fail_step \"uncage setup\" \"$setup_cmd\"\n  else\n    with_node \"$UNCAGE\" setup \"$SITE_URL\" </dev/null 3<&- || fail_step \"uncage setup\" \"$setup_cmd\"\n  fi\n  print_where\n  say 'done'\n}\n\nmain() {\n  uncage_config\n  uncage_extension\n  UNCAGE_TTY_PATH=\"${UNCAGE_TTY:-/dev/tty}\"\n  TTY_OPEN=0\n  parse_args \"$@\"\n  pick_lang\n  if [ \"$SHOW_HELP\" = 1 ]; then\n    say help\n    exit 0\n  fi\n  if [ -n \"$UNKNOWN_OPT\" ]; then\n    warn unknown_option \"$UNKNOWN_OPT\"\n    exit 1\n  fi\n  detect\n  print_checks\n  gate_without_terminal\n  step_node\n  step_npm_prefix\n  step_cli\n  run_extension\n  step_setup\n}\n\nmain \"$@\"\n";

export const INSTALL_PS1_TEMPLATE: string = "# Uncage installer for Windows. It connects this computer to @@SITE_URL@@.\n#\n#   irm <site>/api/uncage/install.ps1 | iex                                  # asks [Y/n] before every change\n#   & ([scriptblock]::Create((irm <site>/api/uncage/install.ps1))) -Yes      # confirms every install step\n#\n# What it does, in order: checks this computer; installs Node.js 22 when it is missing or too old\n# (with your own version manager when you have one: nvm-windows, fnm or volta; otherwise fnm, per\n# user, with winget or from its release zip) without changing your default Node.js unless you say\n# Y; moves npm's global folder to %USERPROFILE%\\.npm-global when it is not writable; installs the\n# CLI with\n#   npm install -g \"@uncage/cli@@@CLI_RANGE@@\"\n# finds the AI coding agents you already have; and offers to run `uncage setup`.\n# It never asks for admin rights, never installs Node.js with an MSI and never changes $PROFILE\n# (PATH changes go to your user Path). Works in Windows PowerShell 5.1 and PowerShell 7.\n# Options: -Yes, -NoSetup, -Lang en|zh|ja. Env: UNCAGE_YES=1, UNCAGE_NO_SETUP=1, UNCAGE_LANG.\n# Exit codes: 0 done, 1 a step failed, 2 needs a terminal to confirm, 3 unsupported.\n# Under `irm | iex` the result is in $LASTEXITCODE and the window stays open.\n# Everything runs inside one script block, so a cut-off download defines nothing and runs nothing.\nparam([switch]$Yes, [switch]$NoSetup, [string]$Lang)\n\n$uncageState = @{ Code = 1 }\n& {\nparam([bool]$OptYes, [bool]$OptNoSetup, [string]$OptLang)\n$ErrorActionPreference = 'Continue'\n$ProgressPreference = 'SilentlyContinue'\n$U = @{}\n\nfunction Set-UncageConfig {\n  $U.CliRange = '@@CLI_RANGE@@'\n  $U.CliSpec = '@uncage/cli@@@CLI_RANGE@@'\n  $U.SiteUrl = '@@SITE_URL@@'\n  $U.NodeMajor = 22\n  $U.FnmZipUrl = 'https://github.com/Schniz/fnm/releases/latest/download/fnm-windows.zip'\n  $U.WingetFnm = 'winget install --id Schniz.fnm -e --source winget --accept-package-agreements --accept-source-agreements'\n}\n\n# @@MESSAGES@@\n\n# @@EXTENSION@@\n\n# ---- output -----------------------------------------------------------------------------------\n\nfunction Get-UMsg([string]$Key) {\n  $t = $UncageMsgs[$U.Lang]\n  if ($null -eq $t) { $t = $UncageMsgs['en'] }\n  $b = $t[$Key]\n  if (-not $b) { return $Key }\n  return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b))\n}\n\nfunction Write-UErr([string]$Text) {\n  try { [Console]::Error.WriteLine($Text) } catch { Write-Host $Text }\n}\n\nfunction Say([string]$Key) {\n  Write-Host ((Get-UMsg $Key) -f $args)\n}\n\nfunction Warn([string]$Key) {\n  Write-UErr ((Get-UMsg $Key) -f $args)\n}\n\n# A command to run by hand, indented.\nfunction Write-UCmd([string]$Line) {\n  Write-Host ('    ' + $Line)\n}\n\nfunction Write-UErrCmd([string]$Line) {\n  Write-UErr ('    ' + $Line)\n}\n\n# Ends the run with a result code (caught in Invoke-UncageMain).\nfunction Stop-Uncage([int]$Code) {\n  $U.Code = $Code\n  throw 'UNCAGE_STOP'\n}\n\n# A step failed: the reason, the commands to run by hand, result 1.\nfunction Stop-UStep([string]$What, [string[]]$Cmds) {\n  Warn 'step_failed' $What\n  if ($Cmds -and $Cmds.Count -gt 0) {\n    Warn 'manual_fix'\n    foreach ($c in $Cmds) { Write-UErrCmd $c }\n  }\n  Stop-Uncage 1\n}\n\n# ---- options, language, terminal --------------------------------------------------------------\n\nfunction Test-UTrue([string]$Value) {\n  return ($Value -match '^(1|true|yes|y)$')\n}\n\n# -Lang > UNCAGE_LANG > the Windows display language (zh*, ja*) > en\nfunction Read-UOptions {\n  $U.Yes = $OptYes -or (Test-UTrue $env:UNCAGE_YES)\n  $U.NoSetup = $OptNoSetup -or (Test-UTrue $env:UNCAGE_NO_SETUP)\n  $l = $OptLang\n  if (-not $l) { $l = $env:UNCAGE_LANG }\n  if (-not $l) {\n    try { $l = (Get-UICulture).Name } catch { $l = '' }\n  }\n  if ($l -like 'zh*') { $U.Lang = 'zh' } elseif ($l -like 'ja*') { $U.Lang = 'ja' } else { $U.Lang = 'en' }\n}\n\n# Answers come from Read-Host. UNCAGE_ANSWERS (comma-separated) replaces it in tests.\nfunction Initialize-UInput {\n  $U.Answers = $null\n  $U.AnswerIdx = 0\n  if ($env:UNCAGE_ANSWERS) {\n    $U.Answers = @($env:UNCAGE_ANSWERS -split ',')\n    $U.Interactive = $true\n    return\n  }\n  $redirected = $true\n  try { $redirected = [Console]::IsInputRedirected } catch { $redirected = $true }\n  $nonInteractive = $false\n  foreach ($a in [Environment]::GetCommandLineArgs()) {\n    if ($a -match '^-noni') { $nonInteractive = $true }\n  }\n  $ci = $env:CI -and ($env:CI -ne 'false') -and ($env:CI -ne '0')\n  $U.Interactive = -not ($redirected -or $nonInteractive -or $ci)\n}\n\n# Ask <message key> [args...]: $true for yes. An empty answer is yes; no answer at all is no.\nfunction Ask([string]$Key) {\n  $m = (Get-UMsg $Key) -f $args\n  Write-Host -NoNewline ($m + ' [Y/n] ')\n  if ($U.Yes) {\n    Write-Host 'Y (-Yes)'\n    return $true\n  }\n  $ans = $null\n  if ($null -ne $U.Answers) {\n    if ($U.AnswerIdx -ge $U.Answers.Count) {\n      Write-Host ''\n      return $false\n    }\n    $ans = $U.Answers[$U.AnswerIdx]\n    $U.AnswerIdx = $U.AnswerIdx + 1\n    Write-Host $ans\n  } elseif ($U.Interactive) {\n    try { $ans = Read-Host } catch { $ans = $null }\n    if ($null -eq $ans) {\n      Write-Host ''\n      return $false\n    }\n  } else {\n    Write-Host ''\n    return $false\n  }\n  $a = ([string]$ans).Trim()\n  return (($a -eq '') -or ($a -match '^(y|yes)$'))\n}\n\n# ---- small helpers ----------------------------------------------------------------------------\n\nfunction Test-UFile([string]$Path) {\n  if (-not $Path) { return $false }\n  return (Test-Path -LiteralPath $Path -PathType Leaf)\n}\n\nfunction Test-UDir([string]$Path) {\n  if (-not $Path) { return $false }\n  return (Test-Path -LiteralPath $Path -PathType Container)\n}\n\n# The first program called $Name on PATH (.exe, .cmd, ...; never a .ps1), or ''.\nfunction Find-UCmd([string]$Name) {\n  $c = Get-Command -Name $Name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1\n  if ($c) { return [string]$c.Path }\n  return ''\n}\n\n# $Dir\\$Name.exe (or .cmd), or ''.\nfunction Find-UExe([string]$Dir, [string]$Name) {\n  if (-not $Dir) { return '' }\n  foreach ($ext in @('.exe', '.cmd')) {\n    $p = Join-Path $Dir ($Name + $ext)\n    if (Test-UFile $p) { return $p }\n  }\n  return ''\n}\n\n# Runs a program for its output (stderr dropped). Returns the output as one string, '' on failure.\nfunction Invoke-UQuery([string]$Exe, [string[]]$Argv) {\n  if (-not $Exe) { return '' }\n  $out = ''\n  try {\n    $lines = & $Exe @Argv 2>$null\n    $out = (@($lines) | ForEach-Object { [string]$_ }) -join \"`n\"\n  } catch {\n    $out = ''\n  }\n  return $out\n}\n\n# Runs a program with its output on the console. The result is in $LASTEXITCODE (1 when it\n# could not start at all).\nfunction Invoke-UNative([string]$Exe, [string[]]$Argv) {\n  $global:LASTEXITCODE = 1\n  try {\n    & $Exe @Argv\n  } catch {\n    Write-UErr ([string]$_)\n    $global:LASTEXITCODE = 1\n  }\n}\n\n# A PowerShell single-quoted literal, for printed commands.\nfunction Format-ULiteral([string]$Text) {\n  return (\"'\" + $Text.Replace(\"'\", \"''\") + \"'\")\n}\n\nfunction Get-UFirstLine([string]$Text) {\n  foreach ($l in ($Text -split \"`r?`n\")) {\n    if ($l.Trim() -ne '') { return $l.Trim() }\n  }\n  return ''\n}\n\nfunction Get-USemver([string]$Text) {\n  if ($Text -match '(\\d+)\\.(\\d+)\\.(\\d+)') { return ($Matches[1] + '.' + $Matches[2] + '.' + $Matches[3]) }\n  return ''\n}\n\nfunction Test-UNodeMajor([string]$Version) {\n  if ($Version -match '^(\\d+)\\.') { return ([int]$Matches[1] -ge $U.NodeMajor) }\n  return $false\n}\n\n# True when $Dir (or its nearest existing parent) takes a new file.\nfunction Test-UWritable([string]$Dir) {\n  $d = $Dir\n  while ($d -and -not (Test-Path -LiteralPath $d)) {\n    $up = Split-Path -Parent $d\n    if (-not $up -or $up -eq $d) { return $false }\n    $d = $up\n  }\n  if (-not (Test-UDir $d)) { return $false }\n  $probe = Join-Path $d ('.uncage-write-test-' + [Guid]::NewGuid().ToString('N'))\n  try {\n    [IO.File]::WriteAllText($probe, '')\n    Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue\n    return $true\n  } catch {\n    return $false\n  }\n}\n\n# Does installed version $Version satisfy the major.minor of the CLI range?\nfunction Test-URange([string]$Version) {\n  $r = $U.CliRange\n  if ($r -eq 'latest' -or $r -eq 'next') { return $true }\n  $op = ''\n  if ($r.StartsWith('^')) {\n    $op = '^'\n    $r = $r.Substring(1)\n  } elseif ($r.StartsWith('~')) {\n    $op = '~'\n    $r = $r.Substring(1)\n  }\n  if (-not ($r -match '^(\\d+)(\\.(\\d+))?')) { return $false }\n  $rmaj = [int]$Matches[1]\n  $rmin = $null\n  if ($Matches[3]) { $rmin = [int]$Matches[3] }\n  if (-not ($Version -match '^(\\d+)\\.(\\d+)')) { return $false }\n  $vmaj = [int]$Matches[1]\n  $vmin = [int]$Matches[2]\n  if ($vmaj -ne $rmaj) { return $false }\n  if ($null -eq $rmin) { return $true }\n  if ($op -eq '^' -and $rmaj -gt 0) { return ($vmin -ge $rmin) }\n  return ($vmin -eq $rmin)\n}\n\n# ---- the user Path (never $PROFILE: the default Restricted policy does not load it) ------------\n\nfunction Get-UUserPath {\n  if ($env:UNCAGE_TEST_USER_PATH_FILE) {\n    if (-not (Test-UFile $env:UNCAGE_TEST_USER_PATH_FILE)) { return '' }\n    return ([string](Get-Content -LiteralPath $env:UNCAGE_TEST_USER_PATH_FILE -Raw)).Trim()\n  }\n  $key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Environment')\n  if ($null -eq $key) { return '' }\n  try {\n    # Raw value: entries like %USERPROFILE%\\bin stay unexpanded when it is written back.\n    return [string]$key.GetValue('Path', '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)\n  } finally {\n    $key.Close()\n  }\n}\n\nfunction Set-UUserPath([string]$Value) {\n  if ($env:UNCAGE_TEST_USER_PATH_FILE) {\n    [IO.File]::WriteAllText($env:UNCAGE_TEST_USER_PATH_FILE, $Value)\n    return\n  }\n  $key = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Environment')\n  try {\n    $key.SetValue('Path', $Value, [Microsoft.Win32.RegistryValueKind]::ExpandString)\n  } finally {\n    $key.Close()\n  }\n  # SetEnvironmentVariable broadcasts WM_SETTINGCHANGE, so new terminals see the new Path.\n  try {\n    [Environment]::SetEnvironmentVariable('UNCAGE_PATH_REFRESH', '1', 'User')\n    [Environment]::SetEnvironmentVariable('UNCAGE_PATH_REFRESH', $null, 'User')\n  } catch { }\n}\n\n# Appends $Dir to the user Path once.\nfunction Add-UUserPath([string]$Dir) {\n  $cur = Get-UUserPath\n  $parts = @($cur -split ';' | Where-Object { $_ -ne '' })\n  $want = $Dir.TrimEnd('\\')\n  foreach ($p in $parts) {\n    if ([Environment]::ExpandEnvironmentVariables($p).TrimEnd('\\') -ieq $want) { return }\n  }\n  $parts += $Dir\n  Set-UUserPath ($parts -join ';')\n  $U.AddedPaths += $Dir\n  Say 'path_added' $Dir\n}\n\n# The Machine Path comes before the user Path in every new terminal.\nfunction Get-UMachinePath {\n  if ($env:UNCAGE_TEST_MACHINE_PATH_FILE) {\n    if (-not (Test-UFile $env:UNCAGE_TEST_MACHINE_PATH_FILE)) { return '' }\n    return ([string](Get-Content -LiteralPath $env:UNCAGE_TEST_MACHINE_PATH_FILE -Raw)).Trim()\n  }\n  try { return [string][Environment]::GetEnvironmentVariable('Path', 'Machine') } catch { return '' }\n}\n\n# A node.exe in a Machine Path folder other than Node.js 22's own, or ''.\nfunction Find-UMachineNode {\n  $mine = (Split-Path -Parent $U.NewNode).TrimEnd('\\')\n  foreach ($p in ((Get-UMachinePath) -split ';')) {\n    if (-not $p) { continue }\n    $d = [Environment]::ExpandEnvironmentVariables($p).TrimEnd('\\')\n    if ($d -ieq $mine) { continue }\n    $n = Find-UExe $d 'node'\n    if ($n) { return $n }\n  }\n  return ''\n}\n\n# ---- step 1: checks ---------------------------------------------------------------------------\n\nfunction Test-UPlatform {\n  $arch = $env:PROCESSOR_ARCHITEW6432\n  if (-not $arch) { $arch = $env:PROCESSOR_ARCHITECTURE }\n  $U.ArchRaw = [string]$arch\n  $U.Arch = ''\n  if ($U.ArchRaw -ieq 'AMD64') { $U.Arch = 'x64' } elseif ($U.ArchRaw -ieq 'ARM64') { $U.Arch = 'arm64' }\n  $onWindows = ($env:OS -eq 'Windows_NT')\n  if (-not $onWindows -or -not $U.Arch) {\n    $os = 'Windows'\n    if (-not $onWindows) { $os = [string][Environment]::OSVersion.Platform }\n    Warn 'os_unsupported' $os $U.ArchRaw\n    Stop-Uncage 3\n  }\n  $U.OwnFnmDir = Join-Path $env:LOCALAPPDATA 'fnm'\n  $U.NpmGlobal = Join-Path $env:USERPROFILE '.npm-global'\n}\n\nfunction Get-UNodeVersion([string]$Node) {\n  return (Get-USemver (Invoke-UQuery $Node @('--version')))\n}\n\n# npm runs as `node npm-cli.js`: npm.cmd would go through cmd.exe, which eats the ^ of a range.\nfunction Invoke-UNpmQuery([string[]]$Argv) {\n  return (Get-UFirstLine (Invoke-UQuery $U.Node (@($U.NpmCli) + $Argv)))\n}\n\n# Uses node $Node: sets Node, NodeDir, NpmCli, NpmVer, NpmPrefix, NpmWritable, and puts the\n# Node.js folder first on this process's PATH (npm and the uncage.cmd shim start `node`).\nfunction Use-UNode([string]$Node) {\n  $U.Node = $Node\n  $U.NodeDir = Split-Path -Parent $Node\n  $env:Path = $U.NodeDir + [IO.Path]::PathSeparator + $U.BasePath\n  $U.NpmCli = Join-Path $U.NodeDir 'node_modules\\npm\\bin\\npm-cli.js'\n  $U.NpmVer = ''\n  $U.NpmPrefix = ''\n  $U.NpmWritable = $false\n  if (-not (Test-UFile $U.NpmCli)) {\n    $U.NpmCli = ''\n    return\n  }\n  $U.NpmVer = Invoke-UNpmQuery @('--version')\n  $U.NpmPrefix = Invoke-UNpmQuery @('prefix', '-g')\n  if ($U.NpmPrefix -and (Test-UWritable $U.NpmPrefix)) { $U.NpmWritable = $true }\n}\n\n# The CLI is always run as uncage.cmd by its full path: under the default Restricted execution\n# policy PowerShell refuses npm's PowerShell shim, which it would pick first for a bare `uncage`.\nfunction Find-UCli {\n  $U.Uncage = ''\n  $U.CliVer = ''\n  $c = ''\n  if ($U.NpmPrefix) {\n    $p = Join-Path $U.NpmPrefix 'uncage.cmd'\n    if (Test-UFile $p) { $c = $p }\n  }\n  if (-not $c) { $c = Find-UCmd 'uncage.cmd' }\n  if (-not $c) { return }\n  $U.Uncage = $c\n  $U.CliVer = Get-USemver (Invoke-UQuery $c @('--version'))\n}\n\nfunction Test-UCliOk {\n  return ([bool]$U.Uncage -and [bool]$U.CliVer -and (Test-URange $U.CliVer))\n}\n\nfunction Find-UAgents {\n  $U.Claude = Find-UCmd 'claude'\n  if (-not $U.Claude) { $U.Claude = Find-UExe (Join-Path $env:USERPROFILE '.local\\bin') 'claude' }\n  $U.Codex = Find-UCmd 'codex'\n}\n\n# Version managers, in order of preference: nvm-windows, fnm, volta.\nfunction Find-UManager {\n  $U.Mgr = ''\n  $U.MgrLabel = ''\n  $U.Fnm = ''\n  $U.Volta = ''\n  $U.Nvm = Find-UCmd 'nvm'\n  if (-not $U.Nvm -and $env:NVM_HOME) { $U.Nvm = Find-UExe $env:NVM_HOME 'nvm' }\n  if ($U.Nvm) {\n    $U.Mgr = 'nvm'\n    $U.MgrLabel = 'nvm-windows'\n    return\n  }\n  $U.Fnm = Find-UCmd 'fnm'\n  if (-not $U.Fnm) { $U.Fnm = Find-UExe $U.OwnFnmDir 'fnm' }\n  if (-not $U.Fnm) { $U.Fnm = Find-UExe (Join-Path $env:LOCALAPPDATA 'Microsoft\\WinGet\\Links') 'fnm' }\n  if ($U.Fnm) {\n    $U.Mgr = 'fnm'\n    $U.MgrLabel = 'fnm'\n    return\n  }\n  # volta is unmaintained: an existing install is used, never installed by this script.\n  $U.Volta = Find-UCmd 'volta'\n  if ($U.Volta) {\n    $U.Mgr = 'volta'\n    $U.MgrLabel = 'volta'\n  }\n}\n\nfunction Find-UState {\n  $U.BasePath = $env:Path\n  $U.PathNode = Find-UCmd 'node'\n  $U.PathNodeVer = ''\n  $U.NodeOk = $false\n  $U.Node = ''\n  $U.NodeDir = ''\n  $U.NpmCli = ''\n  $U.NpmVer = ''\n  $U.NpmPrefix = ''\n  $U.NpmWritable = $false\n  $U.Uncage = ''\n  $U.CliVer = ''\n  $U.NodeIsDefault = $true\n  $U.InstalledNow = $false\n  $U.HadDefault = $true\n  if ($U.PathNode) {\n    $U.PathNodeVer = Get-UNodeVersion $U.PathNode\n    if (Test-UNodeMajor $U.PathNodeVer) {\n      # Shims (volta, scoop) are not next to npm: use the real node.exe.\n      $real = Get-UFirstLine (Invoke-UQuery $U.PathNode @('-p', 'process.execPath'))\n      $n = $U.PathNode\n      if (Test-UFile $real) { $n = $real }\n      Use-UNode $n\n      if ($U.NpmCli) { $U.NodeOk = $true }\n    }\n  }\n  if ($U.NodeOk) { Find-UCli }\n  Find-UAgents\n  Find-UManager\n  $U.Winget = Find-UCmd 'winget'\n}\n\nfunction Write-UChecks {\n  Say 'checking'\n  Say 'os_ok' 'Windows' $U.Arch\n  if ($U.NodeOk) {\n    Say 'node_ok' $U.PathNodeVer $U.PathNode\n    if ($U.NpmWritable) { Say 'npm_ok' $U.NpmVer $U.NpmPrefix } else { Say 'npm_not_writable' $U.NpmVer $U.NpmPrefix }\n    if (Test-UCliOk) {\n      Say 'cli_ok' $U.CliVer $U.Uncage\n    } elseif ($U.Uncage) {\n      $v = $U.CliVer\n      if (-not $v) { $v = '?' }\n      Say 'cli_old' $v $U.CliRange\n    } else {\n      Say 'cli_missing'\n    }\n  } else {\n    if (-not $U.PathNode -or -not $U.PathNodeVer) {\n      Say 'node_missing'\n    } elseif (-not (Test-UNodeMajor $U.PathNodeVer)) {\n      Say 'node_old' $U.PathNodeVer\n    } else {\n      Say 'npm_missing'\n    }\n    Say 'later'\n  }\n  if ($U.Claude) { Say 'agent_ok' 'Claude Code' $U.Claude } else { Say 'agent_missing' 'Claude Code' }\n  if ($U.Codex) { Say 'agent_ok' 'Codex' $U.Codex } else { Say 'agent_missing' 'Codex' }\n  Write-Host ''\n}\n\n# ---- manual commands (no terminal, or a declined / failed step) -------------------------------\n\nfunction Get-UFnmZipManualCmds {\n  return @(\n    ('Invoke-WebRequest -UseBasicParsing ' + $U.FnmZipUrl + ' -OutFile \"$env:TEMP\\fnm-windows.zip\"'),\n    'Expand-Archive \"$env:TEMP\\fnm-windows.zip\" \"$env:LOCALAPPDATA\\fnm\" -Force',\n    ('& \"$env:LOCALAPPDATA\\fnm\\fnm.exe\" install ' + $U.NodeMajor)\n  )\n}\n\nfunction Get-UNodeManualCmds {\n  $m = [string]$U.NodeMajor\n  if ($U.Mgr -eq 'nvm') { return @('nvm install ' + $m) }\n  if ($U.Mgr -eq 'fnm') { return @('& ' + (Format-ULiteral $U.Fnm) + ' install ' + $m) }\n  if ($U.Mgr -eq 'volta') { return @('volta install node@' + $m) }\n  if ($U.Winget) { return @($U.WingetFnm, ('fnm install ' + $m)) }\n  return (Get-UFnmZipManualCmds)\n}\n\n# npm through cmd.exe would drop the ^ of the range unless it is quoted for cmd.exe as well.\nfunction Get-UNpmInstallCmd([string]$Spec) {\n  if ($U.NpmCli) { return ('& ' + (Format-ULiteral $U.Node) + ' ' + (Format-ULiteral $U.NpmCli) + ' install -g ' + (Format-ULiteral $Spec)) }\n  return (\"cmd /c 'npm install -g \" + '\"' + $Spec + '\"' + \"'\")\n}\n\n# Adds a folder to the user Path by hand without flattening %VARIABLES% in it (the registry value\n# is read raw and written back as REG_EXPAND_SZ).\nfunction Get-UPathManualCmd([string]$Dir) {\n  return ('$k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey(''Environment''); $k.SetValue(''Path'', $k.GetValue(''Path'', '''', ''DoNotExpandEnvironmentNames'') + '';' + $Dir + ''', ''ExpandString''); $k.Close()')\n}\n\n# No terminal and no -Yes: list what is missing and how to do it by hand; change nothing.\nfunction Assert-UTerminal {\n  $need = $false\n  if (-not $U.NodeOk) { $need = $true }\n  if ($U.NodeOk -and -not $U.NpmWritable) { $need = $true }\n  if ($U.NodeOk -and -not (Test-UCliOk)) { $need = $true }\n  if (-not $need) { return }\n  if ($U.Yes -or $U.Interactive) { return }\n  Say 'needs_confirm'\n  if (-not $U.NodeOk) {\n    Say 'item_node'\n    foreach ($c in (Get-UNodeManualCmds)) { Write-UCmd $c }\n  }\n  if ($U.NodeOk -and -not $U.NpmWritable) {\n    Say 'item_npm'\n    Write-UCmd 'npm.cmd config set prefix \"$env:USERPROFILE\\.npm-global\"'\n    Write-UCmd (Get-UPathManualCmd '%USERPROFILE%\\.npm-global')\n  }\n  if (-not $U.NodeOk -or -not (Test-UCliOk)) {\n    Say 'item_cli' $U.CliSpec\n    Write-UCmd (Get-UNpmInstallCmd $U.CliSpec)\n  }\n  Say 'item_setup'\n  Write-UCmd ('uncage.cmd setup ' + $U.SiteUrl)\n  Say 'rerun_yes'\n  Stop-Uncage 2\n}\n\n# ---- step 2: Node.js 22 -----------------------------------------------------------------------\n\nfunction Get-UNvmRoot {\n  $out = Invoke-UQuery $U.Nvm @('root')\n  if ($out -match 'Current Root:\\s*([^\\r\\n]+)') { return $Matches[1].Trim().TrimEnd('\\') }\n  if ($env:NVM_HOME) { return $env:NVM_HOME.TrimEnd('\\') }\n  return ''\n}\n\n# fnm keeps its versions and aliases in FNM_DIR, else %USERPROFILE%\\.fnm when it exists, else\n# %APPDATA%\\fnm.\nfunction Get-UFnmDir {\n  if ($env:FNM_DIR) { return $env:FNM_DIR }\n  $legacy = Join-Path $env:USERPROFILE '.fnm'\n  if (Test-UDir $legacy) { return $legacy }\n  return (Join-Path $env:APPDATA 'fnm')\n}\n\n# fnm makes the first version it installs the default by itself. The alias tells whether a\n# default existed before this run.\nfunction Test-UDefaultAlias {\n  if ($U.Mgr -ne 'fnm') { return $true }\n  return (Test-Path -LiteralPath (Join-Path (Get-UFnmDir) 'aliases\\default'))\n}\n\n# Call right before installing Node.js with the manager.\nfunction Save-UDefault {\n  $U.InstalledNow = $true\n  $U.HadDefault = Test-UDefaultAlias\n}\n\n# The user kept their default: undo the default fnm created by itself.\nfunction Restore-UDefault {\n  if ($U.Mgr -ne 'fnm' -or -not $U.InstalledNow -or $U.HadDefault -or -not (Test-UDefaultAlias)) { return }\n  $how = @('unalias', 'default')\n  if ($U.PathNode) { $how = @('default', 'system') }\n  $line = 'fnm ' + ($how -join ' ')\n  Invoke-UNative $U.Fnm $how\n  if ($LASTEXITCODE -ne 0) { Stop-UStep $line @($line) }\n  Say 'default_restored' 'fnm'\n}\n\n# node.exe in the newest <Root>\\<Prefix>22.x.y folder, or ''.\nfunction Find-UNewestNode([string]$Root, [string]$Prefix) {\n  if (-not (Test-UDir $Root)) { return '' }\n  $best = ''\n  $bestVer = $null\n  foreach ($d in @(Get-ChildItem -LiteralPath $Root -Directory -ErrorAction SilentlyContinue)) {\n    if ($d.Name -match ('^' + $Prefix + $U.NodeMajor + '\\.(\\d+)\\.(\\d+)$')) {\n      $ver = [version]([string]$U.NodeMajor + '.' + $Matches[1] + '.' + $Matches[2])\n      if ($null -eq $bestVer -or $ver -gt $bestVer) {\n        $bestVer = $ver\n        $best = $d.FullName\n      }\n    }\n  }\n  if (-not $best) { return '' }\n  return (Find-UExe $best 'node')\n}\n\n# Sets NewNode / NodeVer to the manager's Node.js 22 without activating it.\nfunction Find-UMgrNode {\n  $U.NewNode = ''\n  $p = ''\n  if ($U.Mgr -eq 'nvm') {\n    $p = Find-UNewestNode (Get-UNvmRoot) 'v'\n    if ($p) { $U.NvmVersion = Split-Path -Leaf (Split-Path -Parent $p) }\n    if ($U.NvmVersion) { $U.NvmVersion = $U.NvmVersion.TrimStart('v') }\n  } elseif ($U.Mgr -eq 'fnm') {\n    $p = Get-UFirstLine (Invoke-UQuery $U.Fnm @('exec', ('--using=' + $U.NodeMajor), 'node', '-p', 'process.execPath'))\n  } elseif ($U.Mgr -eq 'volta') {\n    # Not `volta run --node 22`: it would download Node.js before the user said Y.\n    $vh = $env:VOLTA_HOME\n    if (-not $vh) { $vh = Join-Path $env:LOCALAPPDATA 'Volta' }\n    $p = Find-UNewestNode (Join-Path $vh 'tools\\image\\node') ''\n  }\n  if (Test-UFile $p) {\n    $v = Get-UNodeVersion $p\n    if (Test-UNodeMajor $v) {\n      $U.NewNode = $p\n      $U.NodeVer = $v\n      return $true\n    }\n  }\n  return $false\n}\n\nfunction Install-UMgrNode {\n  Save-UDefault\n  $m = [string]$U.NodeMajor\n  # `volta install` would also make it the default: fetch only, `install` after a Y.\n  if ($U.Mgr -eq 'nvm') {\n    Invoke-UNative $U.Nvm @('install', $m)\n  } elseif ($U.Mgr -eq 'fnm') {\n    Invoke-UNative $U.Fnm @('install', $m)\n  } elseif ($U.Mgr -eq 'volta') {\n    Invoke-UNative $U.Volta @('fetch', ('node@' + $m))\n  }\n  if ($LASTEXITCODE -ne 0) { Stop-UStep ($U.MgrLabel + ' install') (Get-UNodeManualCmds) }\n}\n\nfunction Stop-UNodeDeclined {\n  Say 'node_required'\n  foreach ($c in (Get-UNodeManualCmds)) { Write-UCmd $c }\n  Stop-Uncage 0\n}\n\nfunction Install-UFnmZip {\n  $tmp = Join-Path ([IO.Path]::GetTempPath()) ('uncage-install-' + [Guid]::NewGuid().ToString('N'))\n  $ok = $false\n  $err = ''\n  try {\n    New-Item -ItemType Directory -Path $tmp -Force | Out-Null\n    $zip = Join-Path $tmp 'fnm-windows.zip'\n    if ($env:UNCAGE_TEST_FNM_ZIP) {\n      Copy-Item -LiteralPath $env:UNCAGE_TEST_FNM_ZIP -Destination $zip -ErrorAction Stop\n    } else {\n      # Windows PowerShell 5.1 may not offer TLS 1.2 by default.\n      [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12\n      Invoke-WebRequest -UseBasicParsing -Uri $U.FnmZipUrl -OutFile $zip -ErrorAction Stop\n    }\n    New-Item -ItemType Directory -Path $U.OwnFnmDir -Force | Out-Null\n    Expand-Archive -LiteralPath $zip -DestinationPath $U.OwnFnmDir -Force -ErrorAction Stop\n    $ok = $true\n  } catch {\n    $err = [string]$_\n  } finally {\n    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue\n  }\n  if (-not $ok) {\n    if ($err) { Write-UErr $err }\n    Stop-UStep ('download ' + $U.FnmZipUrl) (Get-UFnmZipManualCmds)\n  }\n}\n\nfunction Find-UWingetFnm {\n  $fnm = Find-UExe (Join-Path $env:LOCALAPPDATA 'Microsoft\\WinGet\\Links') 'fnm'\n  if ($fnm) { return $fnm }\n  $pkgs = Join-Path $env:LOCALAPPDATA 'Microsoft\\WinGet\\Packages'\n  if (-not (Test-UDir $pkgs)) { return '' }\n  foreach ($d in @(Get-ChildItem -LiteralPath $pkgs -Directory -Filter 'Schniz.fnm*' -ErrorAction SilentlyContinue)) {\n    $fnm = Find-UExe $d.FullName 'fnm'\n    if ($fnm) { return $fnm }\n  }\n  return ''\n}\n\n# No version manager: fnm per user (winget's portable package, else the release zip). Never a\n# Node.js MSI: those are machine-wide and need admin rights (UAC).\nfunction Install-UOwnFnm {\n  $fnm = ''\n  if ($U.Winget) {\n    if (-not (Ask 'ask_node_winget')) { Stop-UNodeDeclined }\n    Invoke-UNative $U.Winget @('install', '--id', 'Schniz.fnm', '-e', '--source', 'winget', '--accept-package-agreements', '--accept-source-agreements')\n    $fnm = Find-UWingetFnm\n    if (-not $fnm) { Stop-UStep 'winget install Schniz.fnm' (Get-UNodeManualCmds) }\n  } else {\n    if (-not (Ask 'ask_node_fnm' $U.OwnFnmDir)) { Stop-UNodeDeclined }\n    Install-UFnmZip\n    $fnm = Find-UExe $U.OwnFnmDir 'fnm'\n    if (-not $fnm) { Stop-UStep ('download ' + $U.FnmZipUrl) (Get-UFnmZipManualCmds) }\n    Add-UUserPath $U.OwnFnmDir\n  }\n  $U.Mgr = 'fnm'\n  $U.MgrLabel = 'fnm'\n  $U.Fnm = $fnm\n  Save-UDefault\n  Invoke-UNative $U.Fnm @('install', [string]$U.NodeMajor)\n  if ($LASTEXITCODE -ne 0) { Stop-UStep ('fnm install ' + $U.NodeMajor) @('& ' + (Format-ULiteral $fnm) + ' install ' + $U.NodeMajor) }\n}\n\nfunction Set-UMgrDefault {\n  $m = [string]$U.NodeMajor\n  if ($U.Mgr -eq 'fnm') {\n    Invoke-UNative $U.Fnm @('default', $m)\n    if ($LASTEXITCODE -ne 0) { Stop-UStep 'fnm default' @('fnm default ' + $m) }\n    Add-UUserPath (Join-Path (Get-UFnmDir) 'aliases\\default')\n  } elseif ($U.Mgr -eq 'volta') {\n    Invoke-UNative $U.Volta @('install', ('node@' + $m))\n    if ($LASTEXITCODE -ne 0) { Stop-UStep 'volta install' @('volta install node@' + $m) }\n  }\n}\n\n# Changing the default needs its own Y. Under -Yes only when there was no Node.js at all.\nfunction Set-UDefaultNode {\n  if ($U.Mgr -eq 'nvm') {\n    # `nvm use` makes a symlink, which needs admin rights: never run here.\n    $U.NodeIsDefault = $false\n    Say 'nvm_use_hint' $U.NvmVersion\n    return\n  }\n  $make = $true\n  if ($U.Yes -and $U.PathNode) {\n    $make = $false\n    Say 'default_kept_yes'\n  } elseif (-not (Ask 'ask_default')) {\n    $make = $false\n  }\n  if ($make) {\n    Set-UMgrDefault\n    $other = Find-UMachineNode\n    if ($other) {\n      # The Machine Path comes first, so new terminals would still start that Node.js.\n      $U.NodeIsDefault = $false\n      Warn 'default_shadowed' $other\n    } else {\n      Say 'default_done'\n    }\n  } else {\n    $U.NodeIsDefault = $false\n    Restore-UDefault\n    Say 'default_kept' $U.NewNode\n  }\n}\n\nfunction Invoke-UNodeStep {\n  if ($U.NodeOk) { return }\n  $U.NewNode = ''\n  if ($U.Mgr) {\n    if (Find-UMgrNode) {\n      Say 'node_found_mgr' $U.MgrLabel $U.NewNode\n    } else {\n      if (-not (Ask 'ask_node_mgr' $U.MgrLabel)) { Stop-UNodeDeclined }\n      Install-UMgrNode\n      if (-not (Find-UMgrNode)) { Stop-UStep ($U.MgrLabel + ' install') (Get-UNodeManualCmds) }\n      Say 'node_installed' $U.NodeVer $U.NewNode\n    }\n  } else {\n    Install-UOwnFnm\n    if (-not (Find-UMgrNode)) { Stop-UStep ('fnm install ' + $U.NodeMajor) (Get-UNodeManualCmds) }\n    Say 'node_installed' $U.NodeVer $U.NewNode\n  }\n  Set-UDefaultNode\n  Use-UNode $U.NewNode\n  if (-not $U.NpmCli) { Stop-UStep 'npm' (Get-UNodeManualCmds) }\n  $U.NodeOk = $true\n  Find-UCli\n}\n\n# ---- step 3: npm global folder ----------------------------------------------------------------\n\nfunction Invoke-UNpmPrefixStep {\n  if ($U.NpmWritable) { return }\n  if (-not (Ask 'ask_npm_prefix' $U.NpmPrefix $U.NpmGlobal)) {\n    Say 'declined'\n    Write-UCmd 'npm.cmd config set prefix \"$env:USERPROFILE\\.npm-global\"'\n    Write-UCmd (Get-UPathManualCmd '%USERPROFILE%\\.npm-global')\n    Write-UCmd (Get-UNpmInstallCmd $U.CliSpec)\n    Stop-Uncage 0\n  }\n  New-Item -ItemType Directory -Path $U.NpmGlobal -Force | Out-Null\n  Invoke-UNative $U.Node @($U.NpmCli, 'config', 'set', 'prefix', $U.NpmGlobal)\n  if ($LASTEXITCODE -ne 0) { Stop-UStep 'npm config set prefix' @('npm.cmd config set prefix \"$env:USERPROFILE\\.npm-global\"') }\n  $U.NpmPrefix = $U.NpmGlobal\n  $U.NpmWritable = $true\n  Say 'npm_prefix_done' $U.NpmGlobal\n  Add-UUserPath $U.NpmGlobal\n  Find-UCli\n}\n\n# ---- step 4: the Uncage CLI -------------------------------------------------------------------\n\nfunction Invoke-UCliStep {\n  $spec = $U.CliSpec\n  if ($env:UNCAGE_CLI_SPEC) { $spec = $env:UNCAGE_CLI_SPEC }\n  if (Test-UCliOk) {\n    Say 'cli_skip' $U.CliVer $U.Uncage\n    return\n  }\n  $manual = Get-UNpmInstallCmd $spec\n  if (-not (Ask 'ask_cli' $spec)) {\n    Say 'declined'\n    Write-UCmd $manual\n    Stop-Uncage 0\n  }\n  Invoke-UNative $U.Node @($U.NpmCli, 'install', '-g', $spec)\n  if ($LASTEXITCODE -ne 0) { Stop-UStep ('npm install -g ' + $spec) @($manual) }\n  $U.Uncage = ''\n  $p = Join-Path $U.NpmPrefix 'uncage.cmd'\n  if (Test-UFile $p) { $U.Uncage = $p } else { $U.Uncage = Find-UCmd 'uncage.cmd' }\n  if (-not $U.Uncage) { Stop-UStep ('npm install -g ' + $spec) @($manual) }\n  Say 'cli_installed' $U.Uncage\n}\n\n# ---- the site's own step (HubOptions.installScript.ps1AfterCli) --------------------------------\n\n# Runs in its own PowerShell process (so leaving it early never closes this window), with Node.js 22\n# first on PATH and UNCAGE_BIN, UNCAGE_NODE, UNCAGE_SITE_URL set. A non-zero result fails the run.\nfunction Invoke-UExtension {\n  if (-not $UncageExt) { return }\n  Say 'extension_running'\n  $tmp = Join-Path ([IO.Path]::GetTempPath()) ('uncage-install-' + [Guid]::NewGuid().ToString('N'))\n  $saved = @($env:UNCAGE_BIN, $env:UNCAGE_NODE, $env:UNCAGE_SITE_URL)\n  $code = 1\n  try {\n    New-Item -ItemType Directory -Path $tmp -Force | Out-Null\n    $file = Join-Path $tmp 'extension.ps1'\n    [IO.File]::WriteAllText($file, $UncageExt)\n    $env:UNCAGE_BIN = $U.Uncage\n    $env:UNCAGE_NODE = $U.Node\n    $env:UNCAGE_SITE_URL = $U.SiteUrl\n    $shell = (Get-Process -Id $PID).Path\n    Invoke-UNative $shell @('-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $file)\n    $code = $LASTEXITCODE\n  } catch {\n    Write-UErr ([string]$_)\n    $code = 1\n  } finally {\n    $env:UNCAGE_BIN = $saved[0]\n    $env:UNCAGE_NODE = $saved[1]\n    $env:UNCAGE_SITE_URL = $saved[2]\n    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue\n  }\n  if ($code -ne 0) { Stop-UStep (Get-UMsg 'extension_step') @() }\n}\n\n# ---- step 5: agents, then step 6: setup -------------------------------------------------------\n\n# ACP agents count too, once the CLI knows them (`uncage runtimes --json`, when it exists).\nfunction Test-UAcp {\n  $out = Invoke-UQuery $U.Uncage @('runtimes', '--json')\n  return ($out -match '\"status\"\\s*:\\s*\"available\"')\n}\n\nfunction Write-UWhere {\n  if ($U.NodeIsDefault) {\n    Say 'uncage_path' (Format-ULiteral $U.Uncage)\n  } else {\n    Say 'not_default_hint' (Format-ULiteral ($U.NodeDir + ';')) (Format-ULiteral $U.Uncage)\n  }\n}\n\nfunction Invoke-USetupStep {\n  if (-not $U.Claude -and -not $U.Codex -and -not (Test-UAcp)) {\n    Write-Host ''\n    Say 'no_agent'\n    Write-UWhere\n    Stop-Uncage 0\n  }\n  $setup = '& ' + (Format-ULiteral $U.Uncage) + ' setup ' + $U.SiteUrl\n  if (-not $U.NodeIsDefault) { $setup = '$env:Path = ' + (Format-ULiteral ($U.NodeDir + ';')) + ' + $env:Path; ' + $setup }\n  $later = $U.NoSetup -or (-not $U.Yes -and -not $U.Interactive)\n  if ($later -or -not (Ask 'ask_setup' $U.SiteUrl)) {\n    Write-UWhere\n    Say 'setup_later' $setup\n    Stop-Uncage 0\n  }\n  Invoke-UNative $U.Uncage @('setup', $U.SiteUrl)\n  if ($LASTEXITCODE -ne 0) { Stop-UStep 'uncage setup' @($setup) }\n  Write-UWhere\n  Say 'done'\n}\n\nfunction Invoke-UncageSteps {\n  Test-UPlatform\n  Find-UState\n  Write-UChecks\n  Assert-UTerminal\n  Invoke-UNodeStep\n  Invoke-UNpmPrefixStep\n  Invoke-UCliStep\n  Invoke-UExtension\n  Invoke-USetupStep\n}\n\nfunction Invoke-UncageMain {\n  $U.Code = 0\n  $U.AddedPaths = @()\n  $prevPath = $env:Path\n  $prevEnc = $null\n  try {\n    $prevEnc = [Console]::OutputEncoding\n    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding $false\n  } catch {\n    $prevEnc = $null\n  }\n  try {\n    Set-UncageConfig\n    Read-UOptions\n    Initialize-UInput\n    Invoke-UncageSteps\n  } catch {\n    if ([string]$_ -ne 'UNCAGE_STOP') {\n      Write-UErr ('uncage: ' + [string]$_)\n      Write-UErr ([string]$_.InvocationInfo.PositionMessage)\n      $U.Code = 1\n    }\n  } finally {\n    # This window keeps its Path, plus the folders just added to the user Path.\n    $env:Path = $prevPath\n    foreach ($d in $U.AddedPaths) {\n      if (-not (@($env:Path -split ';') -contains $d)) { $env:Path = $env:Path + ';' + $d }\n    }\n    if ($null -ne $prevEnc) {\n      try { [Console]::OutputEncoding = $prevEnc } catch { }\n    }\n  }\n  $uncageState.Code = $U.Code\n}\n\nInvoke-UncageMain\n} ([bool]$Yes) ([bool]$NoSetup) ([string]$Lang)\n\n# Under `irm | iex` this runs in the caller's session: leave only $LASTEXITCODE behind.\nif ($PSCommandPath) { exit $uncageState.Code } else { $global:LASTEXITCODE = $uncageState.Code; Remove-Variable -Name uncageState, Yes, NoSetup, Lang -ErrorAction SilentlyContinue }\n";
